def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = sum(x * x for x in a) ** 0.5
    norm_b = sum(y * y for y in b) ** 0.5
    return dot / (norm_a * norm_b + 1e-9)


image = [0.9, 0.1, 0.1]
labels = {"red square": [0.9, 0.1, 0.1], "blue circle": [0.1, 0.2, 0.9]}

scores = {name: round(cosine(image, vec), 3) for name, vec in labels.items()}
best = max(scores, key=scores.get)
print("scores:", scores)
print("best:", best)
print("confident enough:", scores[best] >= 0.8)   # warna "no match" bolna

