def vector_store_gb(chunks: int, dims: int, bytes_per_value: int = 4, overhead: float = 1.4) -> float:
    raw = chunks * dims * bytes_per_value
    return raw * overhead / 1e9


def index_estimate(docs: int, chunks_per_doc: int, dims: int = 768) -> dict:
    chunks = docs * chunks_per_doc
    return {
        "documents": docs,
        "chunks": chunks,
        "vectors_gb": round(vector_store_gb(chunks, dims), 2),
        "embedding_tokens_m": round(chunks * 350 / 1e6, 1),  # 350 tokens/chunk assumption
    }


for label, est in {
    "pilot 5k docs": index_estimate(5_000, 20),
    "full 50k docs": index_estimate(50_000, 20),
}.items():
    print(label, est)

# Context budget per request
def context_budget(window: int, system: int, history: int, answer_reserve: int, chunk_tokens: int = 350) -> dict:
    available = window - system - history - answer_reserve
    return {
        "available_for_context": available,
        "max_chunks": max(0, available // chunk_tokens),
        "fits": available > 0,
    }


print("8k window :", context_budget(8_000, 600, 800, 700))
print("128k window:", context_budget(128_000, 600, 800, 700))

